package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*; public final class NumberLineSvgRenderer { public String render(NumberLineDiagramSpecV1 s){return render(s,Map.of());} public String render(NumberLineDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),y=s.viewport().height()/2;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(y).append("\" x2=\"").append(s.viewport().width()-p).append("\" y2=\"").append(y).append("\" stroke=\"#000000\"/>");if(s.startArrow())b.append("<path d=\"M ").append(p).append(" ").append(y).append(" l 8 -5 M ").append(p).append(" ").append(y).append(" l 8 5\" stroke=\"#000000\"/>");if(s.endArrow())b.append("<path d=\"M ").append(s.viewport().width()-p).append(" ").append(y).append(" l -8 -5 M ").append(s.viewport().width()-p).append(" ").append(y).append(" l -8 5\" stroke=\"#000000\"/>");for(var point:s.points()){int x=p+20;try{x=p+Integer.parseInt(values.get(point.positionKey()).canonicalValue())*10;}catch(Exception ignored){}b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"5\" fill=\"").append(point.marker()==PointMarker.CLOSED_CIRCLE?"#000000":"#FFFFFF").append("\" stroke=\"#000000\"/>");}for(var interval:s.intervals())b.append("<line x1=\"").append(p+20).append("\" y1=\"").append(y).append("\" x2=\"").append(s.viewport().width()-p-20).append("\" y2=\"").append(y).append("\" stroke=\"#FF0000\" stroke-width=\"2\"/>");return b.toString();} }
